import pickle,re,sys
res=pickle.load(open('res.pkl','rb'))
kw=re.compile(r'fork.?join|doug lea|goetz|concurren|thread.safe|\brace|\bracy|\batomic|transaction|\bSTM\b|\blocks?\b|locking|synchroni|memory model|parallel|work.?steal|FORTRESS_THREADS|mutex|deadlock|\bthreads?\b',re.I)
out={}
for ts,f,inp,cont in res:
  s=cont if isinstance(cont,str) else '\n'.join(i.get('text','') for i in cont if isinstance(i,dict))
