  for line in s.split('\n'):
    if line.startswith('Thread '):thread=line[7:];cur=None;continue
    m=re.match(r'\s*\[(the user[^\]]*?) — ([^\]]*)\]',line)
    if m:
      cur=[m.group(2),thread,[]];out.setdefault((m.group(2),thread),cur);cur=out[(m.group(2),thread)];continue
    if re.match(r'\s*\[',line):cur=None;continue
    m=re.match(r'\s+[0-9a-f]{8}\| ?(.*)',line)
    if m and cur is not None and m.group(1) not in cur[2]:cur[2].append(m.group(1))
print(len(out))
for k in sorted(out):
  t='\n'.join(out[k][2])
  if kw.search(t):print(k,len(t),[x.group(0) for x in kw.finditer(t)][:5])
pickle.dump(out,open('pc.pkl','wb'))
